const TRIAGE_LABELS = [
  'triage:pending', 'triage:in-progress', 'triage:needs-info',
  'triage:needs-reproduction', 'triage:ready-for-review', 'triage:complete',
  'triage:stalled', 'triage:ping', 'triage:tests-needed',
];

const TEAM_LABELS = [
  'team:nodes', 'team:ai', 'team:api', 'team:iam', 'team:chat', 'team:design',
  'team:qa-dx', 'team:lifecycle', 'team:relay', 'team:identity', 'team:cats',
  'team:payday', 'team:adore', 'team:ins', 'team:instance-ai',
];

const CLOSED_LABELS = [
  'closed:duplicate', 'closed:cant-reproduce', 'closed:working-as-expected',
  'closed:support-issue', 'closed:incomplete-template',
  'closed:enhancement/feature', 'closed:info', 'closed:non-english',
  'closed:requested',
];

const ALL_FILTER_LABELS = [...TRIAGE_LABELS, ...TEAM_LABELS, ...CLOSED_LABELS];

// Spec section 8 headline: the rejection reasons which say the issue should
// never have been filed as a bug at all. A subset of CLOSED_LABELS. An issue
// carrying two of them is counted once.
const SHOULD_NOT_HAVE_BEEN_FILED = [
  'closed:incomplete-template', 'closed:support-issue', 'closed:non-english',
];

// Retained deliberately: these matched ZERO issues in the measured population
// because they never co-occur with the 33 filter labels. They cost nothing and
// n8n's labelling may change. Do not delete them assuming they are broken.
const ADHOC_COMPONENT_LABELS = [
  'core', 'ui', 'dx', 'deployment', 'performance', 'security',
];



const ISSUES_QUERY = `
query($cursor: String, $labels: [String!]!, $since: DateTime) {
  rateLimit { cost remaining }
  repository(owner: "n8n-io", name: "n8n") {
    issues(first: 100, after: $cursor, labels: $labels,
           filterBy: {since: $since},
           orderBy: {field: UPDATED_AT, direction: ASC}) {
      pageInfo { hasNextPage endCursor }
      nodes {
        number title state createdAt updatedAt closedAt
        author { login }
        labels(first: 30) { nodes { name } }
        reactions { totalCount }
        comments { totalCount }
        closedByPullRequestsReferences(first: 5, includeClosedPrs: true) {
          nodes { number createdAt mergedAt
                  files(first: 100) { nodes { path } } }
        }
      }
    }
  }
}`;

async function fetchPage({ token, cursor = null, since = null }) {
  const res = await fetch('https://api.github.com/graphql', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${token}`,
      'Content-Type': 'application/json',
      'User-Agent': 'skomp-n8n-triage-analytics',
    },
    body: JSON.stringify({
      query: ISSUES_QUERY,
      variables: { cursor, since, labels: ALL_FILTER_LABELS },
    }),
  });

  if (!res.ok) throw new Error(`GitHub HTTP ${res.status}: ${await res.text()}`);

  const body = await res.json();
  if (body.errors) throw new Error(`GitHub GraphQL: ${body.errors.map(e => e.message).join('; ')}`);

  const conn = body.data.repository.issues;
  return {
    nodes: conn.nodes,
    endCursor: conn.pageInfo.endCursor,
    hasNextPage: conn.pageInfo.hasNextPage,
    cost: body.data.rateLimit.cost,
    remaining: body.data.rateLimit.remaining,
  };
}

async function fetchAll({ token, since = null, onPage = null }) {
  const issues = [];
  let cursor = null, pages = 0, points = 0;

  for (;;) {
    const page = await fetchPage({ token, cursor, since });
    issues.push(...page.nodes);
    pages += 1;
    points += page.cost;
    if (onPage) onPage({ pages, points, received: issues.length, remaining: page.remaining });
    if (!page.hasNextPage) break;
    // A repeated endCursor means the API cannot advance. A silent `break` here
    // would return a short result indistinguishable from a complete one, and
    // the caller would write a truncated store while reporting success. Throw
    // instead, so the stall is diagnosable and cannot be mistaken for done.
    if (page.endCursor === cursor) {
      throw new Error(
        `fetchAll: stalled cursor "${cursor}" did not advance after ${pages} page(s) ` +
        `and ${issues.length} issue(s) collected`
      );
    }
    cursor = page.endCursor;
  }

  return { issues, pages, points };
}


function parseStore(text) {
  const map = new Map();
  for (const line of text.split('\n')) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    const issue = JSON.parse(trimmed);
    map.set(issue.number, issue);
  }
  return map;
}

function serialiseStore(map) {
  return [...map.values()]
    .sort((a, b) => a.number - b.number)
    .map(i => JSON.stringify(i))
    .join('\n') + '\n';
}

function upsert(map, issues) {
  for (const issue of issues) map.set(issue.number, issue);
  return map;
}

function watermarkOf(map) {
  let max = null;
  for (const issue of map.values()) {
    if (issue.updatedAt && (max === null || issue.updatedAt > max)) max = issue.updatedAt;
  }
  return max;
}



const OVERLAP_MS = 5 * 60 * 1000;

// Deliberately re-fetch a 5-minute overlap. Duplicates are cheap because
// upsert is keyed on issue number; a gap is silent and permanent.
function overlapWindow(watermark) {
  if (!watermark) return null;
  return new Date(Date.parse(watermark) - OVERLAP_MS).toISOString().replace(/\.\d{3}Z$/, 'Z');
}

async function syncSince(store, { token }) {
  const since = overlapWindow(watermarkOf(store));
  const { issues } = await fetchAll({ token, since });
  upsert(store, issues);
  return { store, fetched: issues.length, watermark: watermarkOf(store) };
}


function isStalledCursorError(err) {
  return typeof err?.message === 'string' && err.message.startsWith('fetchAll: stalled cursor');
}

function isSecondaryRateLimitError(err) {
  const msg = String(err?.message ?? '');
  return /^GitHub HTTP 403:/.test(msg) && /secondary rate limit|abuse detection/i.test(msg);
}

async function fetchAllWithRetry(fetchAllFn, opts, {
  maxAttempts = 3,
  waitMs = 5 * 60 * 1000,
  sleep = ms => new Promise(resolve => setTimeout(resolve, ms)),
} = {}) {
  let lastErr;
  for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
    try {
      return await fetchAllFn(opts);
    } catch (err) {
      // Hard failure: never retry. A stalled cursor will not un-stall itself.
      if (isStalledCursorError(err)) throw err;
      // Anything that is not the transient secondary rate limit is also a
      // hard failure for this wrapper — only that one condition is retryable.
      if (!isSecondaryRateLimitError(err) || attempt === maxAttempts) throw err;
      lastErr = err;
      await sleep(waitMs);
    }
  }
  throw lastErr;
}

async function runIngest({ stateText, storeText, token, fetchAllFn = fetchAll }) {
  const store = parseStore(storeText ?? '');
  const state = stateText ? JSON.parse(stateText) : {};
  const since = overlapWindow(state.watermark ?? watermarkOf(store));
  const { issues, pages, points } = await fetchAllWithRetry(fetchAllFn, { token, since });
  upsert(store, issues);
  const watermark = watermarkOf(store);
  return {
    storeText: serialiseStore(store),
    stateText: JSON.stringify({ watermark }, null, 2) + '\n',
    fetched: issues.length,
    pages,
    points,
    watermark,
  };
}

// --- n8n driver ---------------------------------------------------------
// This node receives one item per upstream HTTP Request (the GitHub Contents
// API responses for state.json and issues.ndjson, connected into the same
// input). It reads both, runs the sync, and returns a SINGLE item: the two
// downstream "Write" HTTP Request nodes both read their own field off this
// one item, so the item count does not multiply with store size.
const inputs = $input.all();
const stateItem = inputs.find(i => typeof i.json.path === 'string' && i.json.path.endsWith('state.json'));
const storeItem = inputs.find(i => typeof i.json.path === 'string' && i.json.path.endsWith('issues.ndjson'));

const stateText = stateItem ? Buffer.from(stateItem.json.content, 'base64').toString('utf8') : null;
const storeText = storeItem ? Buffer.from(storeItem.json.content, 'base64').toString('utf8') : '';
// ASSUMPTION (unverifiable on the free trial): the instance permits Code-node
// access to environment variables. Verify against N8N_BLOCK_ENV_ACCESS_IN_NODE.
const token = $env.GITHUB_TOKEN;

const result = await runIngest({ stateText, storeText, token });

return [{
  json: {
    stateContent: Buffer.from(result.stateText, 'utf8').toString('base64'),
    stateSha: stateItem ? stateItem.json.sha : undefined,
    storeContent: Buffer.from(result.storeText, 'utf8').toString('base64'),
    storeSha: storeItem ? storeItem.json.sha : undefined,
    fetched: result.fetched,
    watermark: result.watermark,
  },
}];
